mapper.select:
SELECT f.id, f.user_id AS userId, f.type, f.content, f.contact, f.reply, f.status, f.handle_time AS handleTime, f.create_time AS createTime, u.username AS username, u.nickname AS nickname FROM feedback f LEFT JOIN `user` u ON u.id = f.user_id WHERE f.deleted = 0
AND f.user_id = #{userId}
AND f.status = #{q.status}
AND f.type = #{q.type}
ORDER BY f.status ASC, f.id DESC
